form.addEventListener("submit", function (e) {
  if (nome.value.trim().length < 3) {
    e.preventDefault();
    erro.textContent = "Digite o nome completo.";
  }
});

const idadeNum = Number(idade.value);
if (idadeNum < 14 || idadeNum > 18) {
  e.preventDefault();
  erro.textContent = "A idade deve estar entre 14 e 18.";
}
